import React, { useState, useEffect } from "react";
import { createPoll } from "../services/pollService";

export default function CreatePollPage() {
  const [question, setQuestion] = useState("");
  const [choices, setChoices] = useState(["", ""]); // два порожні поля для початку
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");

  // Завантаження каналів
  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/channels/", {
      headers: {
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      },
    })
      .then((res) => res.json())
      .then((data) => setChannels(Array.isArray(data) ? data : data.results || []))
      .catch((err) => console.error("Помилка завантаження каналів:", err));
  }, [token]);

  const handleChoiceChange = (index, value) => {
    const newChoices = [...choices];
    newChoices[index] = value;
    setChoices(newChoices);
  };

  const addChoice = () => setChoices([...choices, ""]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    if (!selectedChannel) {
      setMessage("❌ Будь ласка, оберіть канал");
      return;
    }

    try {
      await createPoll(
        { question, channelId: selectedChannel, choices },
        token
      );
      setMessage("✅ Опитування успішно створено!");
      setQuestion("");
      setChoices(["", ""]);
      setSelectedChannel("");
    } catch (err) {
      console.error("Помилка створення опитування:", err);
      setMessage("❌ Не вдалося створити опитування");
    }
  };

  return (
    <div className="create-poll-container">
      <h2>Створити опитування</h2>
      {message && <p>{message}</p>}
      <form onSubmit={handleSubmit}>
        <label>
          Питання:
          <input
            type="text"
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            required
          />
        </label>

        <label>
          Виберіть канал:
          <select
            value={selectedChannel}
            onChange={(e) => setSelectedChannel(e.target.value)}
            required
          >
            <option value="">-- Оберіть канал --</option>
            {channels.map((ch) => (
              <option key={ch.id} value={ch.id}>
                {ch.name}
              </option>
            ))}
          </select>
        </label>

        <div>
          <h4>Варіанти відповіді:</h4>
          {choices.map((c, idx) => (
            <input
              key={idx}
              type="text"
              value={c}
              onChange={(e) => handleChoiceChange(idx, e.target.value)}
              required
            />
          ))}
          <button type="button" onClick={addChoice}>
            Додати варіант
          </button>
        </div>

        <button type="submit">Створити опитування</button>
      </form>
    </div>
  );
}
